use crate::load;
use std::fs;
use std::path::Path;

pub fn rim_b(_a: &mut hold::Frost, _b: &hold::Pool) {}

pub fn prep(a: &hold::Sess, b: &hold::Pool) -> hold::Frost {
    let mut frost = fold::rim_a(a, b);
    rim_b(&mut frost, b);
    frost
}

fn quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn bag(ids: &[usize], cells: &[String]) -> Option<Vec<String>> {
    ids.iter().map(|&i| cells.get(i).cloned()).collect()
}

fn pack(values: &[String]) -> String {
    format!("[{}]", values.iter().map(|s| quote(s)).collect::<Vec<_>>().join(","))
}

pub fn dump() -> i32 {
