use std::collections::HashSet;
use std::fs;
use std::path::Path;

const RIM: &str = include_str!("../foldrib/rim.rs");
const POOL: &str = include_str!("../internpit/pool.rs");
const INK: &str = include_str!("../restcue/ink.rs");

fn put(path: &str, text: &str) -> bool {
    fs::write(path, text).is_ok()
}

pub fn rib_d() -> i32 {
    let entries = match fs::read_dir("/app/daycards") {
        Ok(v) => v,
        Err(_) => return 1,
    };
    let mut cards = Vec::new();
    for entry in entries {
        let entry = match entry { Ok(v) => v, Err(_) => return 1 };
        let kind = match entry.file_type() { Ok(v) => v, Err(_) => return 1 };
        if kind.is_file() {
            match fs::read_to_string(entry.path()) {
                Ok(text) => cards.push(text),
                Err(_) => return 1,
            }
        }
    }
    let tree = match fs::read_to_string("/app/vatslip/TREE.txt") {
        Ok(v) => v,
        Err(_) => return 1,
    };
    let named: HashSet<&str> = tree.lines().map(str::trim).filter(|s| !s.is_empty()).collect();
    let words: HashSet<&str> = cards.iter().flat_map(|s| s.split_whitespace()).collect();

    if named.contains("foldrib") && words.contains("freeze") && !put("/app/foldrib/rim.rs", RIM) {
        return 2;
    }
    if named.contains("internpit") && words.contains("cells") && !put("/app/internpit/pool.rs", POOL) {
        return 2;
    }
    if named.contains("restcue") && !put("/app/restcue/ink.rs", INK) {
        return 2;
    }
    if !Path::new("/app/foldrib/rim.rs").is_file()
        || !Path::new("/app/internpit/pool.rs").is_file()
        || !Path::new("/app/restcue/ink.rs").is_file()
    {
        return 2;
    }
    0
}
